SET NOCOUNT ON;
CREATE TABLE #r (id varchar(40), res nvarchar(400));
DECLARE @j nvarchar(max);
-- shape
BEGIN TRY INSERT #r SELECT 'obj-rows', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N'{"a":"x"}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('obj-rows','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'arr-rows', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N'[{"a":"x"},{"a":"y"}]') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('arr-rows','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'empty-arr', CONCAT(COUNT(*),'') FROM OPENJSON(N'[]') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('empty-arr','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'empty-obj', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N'{}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('empty-obj','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'scalar', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N'5') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('scalar','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'string', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N'"s"') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('string','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'null-in', CONCAT(COUNT(*),'') FROM OPENJSON(NULL) WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('null-in','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'emptystr', CONCAT(COUNT(*),'') FROM OPENJSON(N'') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('emptystr','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'invalid', CONCAT(COUNT(*),'') FROM OPENJSON(N'{"a":}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('invalid','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'ws', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N' {"a":"x"} ') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('ws','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'arr-mixed', STRING_AGG(CONCAT('[',a,']'),',') FROM OPENJSON(N'[1,{"a":"y"},"s",null,[1]]') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('arr-mixed','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'arr-mixed-n', CONCAT(COUNT(*),'') FROM OPENJSON(N'[1,{"a":"y"},"s",null,[1]]') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('arr-mixed-n','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'arr-strict-mixed', CONCAT(COUNT(*),'') FROM OPENJSON(N'[1,{"a":"y"}]') WITH (a nvarchar(10) 'strict $.a'); END TRY BEGIN CATCH INSERT #r VALUES('arr-strict-mixed','ERR '+ERROR_MESSAGE()) END CATCH
-- paths
BEGIN TRY INSERT #r SELECT 'lax-missing', ISNULL(a,'<null>') FROM OPENJSON(N'{"b":1}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('lax-missing','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'strict-missing', ISNULL(a,'<null>') FROM OPENJSON(N'{"b":1}') WITH (a nvarchar(10) 'strict $.a'); END TRY BEGIN CATCH INSERT #r VALUES('strict-missing','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'strict-null', ISNULL(a,'<null>') FROM OPENJSON(N'{"a":null}') WITH (a nvarchar(10) 'strict $.a'); END TRY BEGIN CATCH INSERT #r VALUES('strict-null','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'lax-obj', ISNULL(a,'<null>') FROM OPENJSON(N'{"a":{"x":1}}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('lax-obj','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'strict-obj', ISNULL(a,'<null>') FROM OPENJSON(N'{"a":{"x":1}}') WITH (a nvarchar(10) 'strict $.a'); END TRY BEGIN CATCH INSERT #r VALUES('strict-obj','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'lax-arr', ISNULL(a,'<null>') FROM OPENJSON(N'{"a":[1]}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('lax-arr','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'strict-arr', ISNULL(a,'<null>') FROM OPENJSON(N'{"a":[1]}') WITH (a nvarchar(10) 'strict $.a'); END TRY BEGIN CATCH INSERT #r VALUES('strict-arr','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'case', ISNULL(a,'<null>') FROM OPENJSON(N'{"A":"x"}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('case','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dup', ISNULL(a,'<null>') FROM OPENJSON(N'{"a":"first","a":"second"}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('dup','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dup-strict', ISNULL(a,'<null>') FROM OPENJSON(N'{"a":"first","a":"second"}') WITH (a nvarchar(10) 'strict $.a'); END TRY BEGIN CATCH INSERT #r VALUES('dup-strict','ERR '+ERROR_MESSAGE()) END CATCH
-- strings
BEGIN TRY INSERT #r SELECT 'trunc', a FROM OPENJSON(N'{"a":"abcdefgh"}') WITH (a nvarchar(5)); END TRY BEGIN CATCH INSERT #r VALUES('trunc','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'trunc-strict', a FROM OPENJSON(N'{"a":"abcdefgh"}') WITH (a nvarchar(5) 'strict $.a'); END TRY BEGIN CATCH INSERT #r VALUES('trunc-strict','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'trunc-surr', CONCAT(LEN(a),':',DATALENGTH(a)) FROM OPENJSON(N'{"a":"a😀bc"}') WITH (a nvarchar(2)); END TRY BEGIN CATCH INSERT #r VALUES('trunc-surr','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'num-str', a FROM OPENJSON(N'{"a":1.50}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('num-str','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'exp-str', a FROM OPENJSON(N'{"a":1e2}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('exp-str','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bool-str', a FROM OPENJSON(N'{"a":true}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('bool-str','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'esc', CONCAT(a,'|',UNICODE(a)) FROM OPENJSON(N'{"a":"é\n"}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('esc','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'trail-sp', CONCAT('[',a,']',LEN(a),':',DATALENGTH(a)) FROM OPENJSON(N'{"a":"x  "}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('trail-sp','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'max', CONCAT(LEN(a),'') FROM OPENJSON(N'{"a":"' + REPLICATE(CAST(N'x' AS nvarchar(max)), 9000) + N'"}') WITH (a nvarchar(max)); END TRY BEGIN CATCH INSERT #r VALUES('max','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'type-str', CAST(SQL_VARIANT_PROPERTY(a,'BaseType') AS nvarchar(40)) FROM OPENJSON(N'{"a":"x"}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('type-str','ERR '+ERROR_MESSAGE()) END CATCH
-- ints
BEGIN TRY INSERT #r SELECT 'int', CONCAT(a,'') FROM OPENJSON(N'{"a":12}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-str', CONCAT(a,'') FROM OPENJSON(N'{"a":"12"}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-str','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-frac', CONCAT(a,'') FROM OPENJSON(N'{"a":12.7}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-frac','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-fracstr', CONCAT(a,'') FROM OPENJSON(N'{"a":"12.7"}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-fracstr','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-exp', CONCAT(a,'') FROM OPENJSON(N'{"a":1e2}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-exp','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-bool', CONCAT(a,'') FROM OPENJSON(N'{"a":true}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-bool','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-big', CONCAT(a,'') FROM OPENJSON(N'{"a":2147483648}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-big','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-neg0', CONCAT(a,'') FROM OPENJSON(N'{"a":-0}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-neg0','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-sp', CONCAT(a,'') FROM OPENJSON(N'{"a":" 12 "}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-sp','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-empty', ISNULL(CONCAT(a,''),'<null>') FROM OPENJSON(N'{"a":""}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-empty','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-obj', ISNULL(CONCAT(a,''),'<null>') FROM OPENJSON(N'{"a":{"x":1}}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-obj','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-null', ISNULL(CONCAT(a,''),'<null>') FROM OPENJSON(N'{"a":null}') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-null','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bigint', CONCAT(a,'') FROM OPENJSON(N'{"a":9007199254740993}') WITH (a bigint); END TRY BEGIN CATCH INSERT #r VALUES('bigint','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bigint-frac', CONCAT(a,'') FROM OPENJSON(N'{"a":5.5}') WITH (a bigint); END TRY BEGIN CATCH INSERT #r VALUES('bigint-frac','ERR '+ERROR_MESSAGE()) END CATCH
-- decimal
BEGIN TRY INSERT #r SELECT 'dec', CONCAT(a,'') FROM OPENJSON(N'{"a":1.005}') WITH (a decimal(18,2)); END TRY BEGIN CATCH INSERT #r VALUES('dec','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dec-neg', CONCAT(a,'') FROM OPENJSON(N'{"a":-1.005}') WITH (a decimal(18,2)); END TRY BEGIN CATCH INSERT #r VALUES('dec-neg','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dec-str', CONCAT(a,'') FROM OPENJSON(N'{"a":"1.005"}') WITH (a decimal(18,2)); END TRY BEGIN CATCH INSERT #r VALUES('dec-str','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dec-exp', CONCAT(a,'') FROM OPENJSON(N'{"a":1e2}') WITH (a decimal(18,2)); END TRY BEGIN CATCH INSERT #r VALUES('dec-exp','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dec-big', CONCAT(a,'') FROM OPENJSON(N'{"a":1234567890123456789}') WITH (a decimal(18,2)); END TRY BEGIN CATCH INSERT #r VALUES('dec-big','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dec-bool', CONCAT(a,'') FROM OPENJSON(N'{"a":true}') WITH (a decimal(18,2)); END TRY BEGIN CATCH INSERT #r VALUES('dec-bool','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dec-3', CONCAT(a,'') FROM OPENJSON(N'{"a":2.0005}') WITH (a decimal(18,3)); END TRY BEGIN CATCH INSERT #r VALUES('dec-3','ERR '+ERROR_MESSAGE()) END CATCH
-- date
BEGIN TRY INSERT #r SELECT 'date', CONCAT(a,'') FROM OPENJSON(N'{"a":"2020-01-31"}') WITH (a date); END TRY BEGIN CATCH INSERT #r VALUES('date','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'date-ts', CONCAT(a,'') FROM OPENJSON(N'{"a":"2020-01-31T10:00:00"}') WITH (a date); END TRY BEGIN CATCH INSERT #r VALUES('date-ts','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'date-compact', CONCAT(a,'') FROM OPENJSON(N'{"a":"20200131"}') WITH (a date); END TRY BEGIN CATCH INSERT #r VALUES('date-compact','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'date-num', CONCAT(a,'') FROM OPENJSON(N'{"a":20200131}') WITH (a date); END TRY BEGIN CATCH INSERT #r VALUES('date-num','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'date-slash', CONCAT(a,'') FROM OPENJSON(N'{"a":"01/02/2020"}') WITH (a date); END TRY BEGIN CATCH INSERT #r VALUES('date-slash','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'date-bad', CONCAT(a,'') FROM OPENJSON(N'{"a":"2020-02-30"}') WITH (a date); END TRY BEGIN CATCH INSERT #r VALUES('date-bad','ERR '+ERROR_MESSAGE()) END CATCH
-- bit
BEGIN TRY INSERT #r SELECT 'bit-true', CONCAT(a,'') FROM OPENJSON(N'{"a":true}') WITH (a bit); END TRY BEGIN CATCH INSERT #r VALUES('bit-true','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bit-false', CONCAT(a,'') FROM OPENJSON(N'{"a":false}') WITH (a bit); END TRY BEGIN CATCH INSERT #r VALUES('bit-false','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bit-1', CONCAT(a,'') FROM OPENJSON(N'{"a":1}') WITH (a bit); END TRY BEGIN CATCH INSERT #r VALUES('bit-1','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bit-2', CONCAT(a,'') FROM OPENJSON(N'{"a":2}') WITH (a bit); END TRY BEGIN CATCH INSERT #r VALUES('bit-2','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bit-str', CONCAT(a,'') FROM OPENJSON(N'{"a":"true"}') WITH (a bit); END TRY BEGIN CATCH INSERT #r VALUES('bit-str','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bit-yes', CONCAT(a,'') FROM OPENJSON(N'{"a":"yes"}') WITH (a bit); END TRY BEGIN CATCH INSERT #r VALUES('bit-yes','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bit-frac', CONCAT(a,'') FROM OPENJSON(N'{"a":0.5}') WITH (a bit); END TRY BEGIN CATCH INSERT #r VALUES('bit-frac','ERR '+ERROR_MESSAGE()) END CATCH
SELECT id + ' => ' + ISNULL(res,'<NULL>') FROM #r;
